ALTER TABLE revisoes_pares ADD COLUMN IF NOT EXISTS rubrica JSON NULL, ADD COLUMN IF NOT EXISTS qualidade TINYINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS moderacao ENUM('NAO_ANALISADA','APROVADA','SINALIZADA','REMOVIDA') NOT NULL DEFAULT 'NAO_ANALISADA';
CREATE TABLE IF NOT EXISTS denuncias_revisao (id_denuncia INT AUTO_INCREMENT PRIMARY KEY,id_revisao_par INT NOT NULL,denunciado_por INT NOT NULL,motivo ENUM('OFENSIVO','INADEQUADO','SPAM','OUTRO') NOT NULL,detalhes VARCHAR(500) NULL,status ENUM('ABERTA','PROCEDENTE','IMPROCEDENTE') NOT NULL DEFAULT 'ABERTA',analisada_por INT NULL,criada_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_denuncia_usuario(id_revisao_par,denunciado_por),INDEX idx_denuncia_status(status,criada_em),CONSTRAINT fk_dr_revisao FOREIGN KEY(id_revisao_par) REFERENCES revisoes_pares(id_revisao_par) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
